// Groups rows by date, computes today-vs-yesterday deltas per KPI, flags anomalies,
// builds an 8-day trend series for the chart, and computes true month-to-date budget pacing.
const rows = items.map(i => i.json);

const byDate = {};
for (const r of rows) {
  const d = r.date;
  byDate[d] = byDate[d] || [];
  byDate[d].push(r);
}
const dates = Object.keys(byDate).sort();
const latest = dates[dates.length - 1];
const prior = dates[dates.length - 2];

function totals(dateRows) {
  const t = { spend: 0, revenue: 0, leads: 0 };
  for (const r of dateRows) {
    t.spend += Number(r.spend);
    t.revenue += Number(r.revenue);
    t.leads += Number(r.leads);
  }
  t.roas = t.spend > 0 ? +(t.revenue / t.spend).toFixed(2) : 0;
  return t;
}

const todayTotals = totals(byDate[latest] || []);
const yestTotals = prior ? totals(byDate[prior] || []) : todayTotals;

function deltaPct(today, yest) {
  return yest > 0 ? +(((today - yest) / yest) * 100).toFixed(1) : 0;
}
const deltas = {
  revenue: deltaPct(todayTotals.revenue, yestTotals.revenue),
  spend: deltaPct(todayTotals.spend, yestTotals.spend),
  leads: deltaPct(todayTotals.leads, yestTotals.leads),
  roas: deltaPct(todayTotals.roas, yestTotals.roas)
};

const anomalies = [];
for (const r of byDate[latest] || []) {
  if (Number(r.roas) < 2.2) {
    anomalies.push({ channel: r.channel, roas: Number(r.roas) });
  }
}

// 8-day trend for the chart
const trendDates = dates.slice(-8);
const trend = trendDates.map(d => {
  const t = totals(byDate[d] || []);
  return { date: d, spend: t.spend, revenue: t.revenue, roas: t.roas };
});

// True month-to-date budget pacing (sums actual spend within the current calendar month)
const monthlyBudget = 6000000; // illustrative, sized to this mock data's ~₹2L/day spend rate — replace with your real monthly budget
const latestDateObj = new Date(latest);
const y = latestDateObj.getFullYear();
const mo = latestDateObj.getMonth();
const dayOfMonth = latestDateObj.getDate();
const daysInMonth = new Date(y, mo + 1, 0).getDate();

let mtdSpend = 0;
for (const d of dates) {
  const dd = new Date(d);
  if (dd.getFullYear() === y && dd.getMonth() === mo && dd <= latestDateObj) {
    mtdSpend += totals(byDate[d]).spend;
  }
}
const expectedFraction = dayOfMonth / daysInMonth;
const pacingPct = expectedFraction > 0 ? Math.round((mtdSpend / monthlyBudget) / expectedFraction * 100) : 100;

return [{
  json: {
    date: latest,
    revenue: todayTotals.revenue,
    spend: todayTotals.spend,
    leads: todayTotals.leads,
    roas: todayTotals.roas,
    deltas,
    anomalies,
    trend,
    budget_pacing_pct: pacingPct,
    mtd_spend: mtdSpend,
    monthly_budget: monthlyBudget
  }
}];

// Always builds a usable executive summary + exactly 3 recommended actions from the metrics —
// no external API. Used as-is if Gemini fails, and as the base object either way.
const m = items[0].json;

const roasTrend = m.deltas.roas > 0 ? `up ${m.deltas.roas}%` : m.deltas.roas < 0 ? `down ${Math.abs(m.deltas.roas)}%` : 'flat';
const pacingWord = m.budget_pacing_pct > 110 ? 'ahead of pace' : m.budget_pacing_pct < 90 ? 'behind pace' : 'on pace';

let summary = `Yesterday's numbers are in: spend ₹${m.spend.toLocaleString('en-IN')}, revenue ₹${m.revenue.toLocaleString('en-IN')}, blended ROAS ${m.roas}x (${roasTrend} day-over-day), ${m.leads} leads. Budget is ${pacingWord} at ${m.budget_pacing_pct}% of the expected month-to-date rate.`;

if (m.anomalies.length) {
  const names = m.anomalies.map(a => `${a.channel} (${a.roas}x)`).join(', ');
  summary += ` ${m.anomalies.length} channel(s) are below the 2.2x ROAS floor: ${names}.`;
} else {
  summary += ' No channels are below the ROAS floor today.';
}

const candidates = [];
if (m.anomalies.length) {
  candidates.push(`Review or pause: ${m.anomalies.map(a => a.channel).join(', ')} — below the 2.2x ROAS floor.`);
}
if (m.budget_pacing_pct > 110) {
  candidates.push('Budget is overpacing — rebalance excess spend toward the highest-ROAS channel today.');
} else if (m.budget_pacing_pct < 90) {
  candidates.push('Budget is underpacing — consider increasing spend on the best-performing channel to stay on track for the month.');
}
if (m.deltas.roas < -5) {
  candidates.push('Blended ROAS dropped more than 5% day-over-day — check for a creative fatigue or audience saturation signal before scaling anything.');
}
candidates.push('No anomalies beyond the above — hold current allocation and re-check tomorrow morning.');
candidates.push('Review the top 3 recommendation cards in the AI Recommendation Engine before 10 AM.');
candidates.push("Confirm yesterday's leads have been picked up by Sales within SLA.");

const actions = candidates.slice(0, 3);

return [{ json: { ...m, summary_text: summary, summary_source: 'fallback', actions } }];

const geminiText = $json.candidates[0].content.parts[0].text.trim();
const base = $('Build Fallback Narrative').item.json;
return [{ json: { ...base, summary_text: geminiText, summary_source: 'gemini' } }];

// Gemini failed or was empty — keep the fallback summary already built.
const base = $('Build Fallback Narrative').item.json;
return [{ json: { ...base } }];

// Builds the full CEO-style HTML infographic email: KPI cards with day-over-day deltas,
// an embedded trend chart (via QuickChart.io's free image API — no key required),
// an anomaly banner, the executive summary, and the 3 recommended actions.
const m = items[0].json;

const chartConfig = {
  type: 'line',
  data: {
    labels: m.trend.map(t => t.date.slice(5)),
    datasets: [
      { label: 'Spend (₹)', data: m.trend.map(t => t.spend), borderColor: '#D5493F', backgroundColor: 'rgba(213,73,63,0.08)', fill: false, tension: 0.3 },
      { label: 'Revenue (₹)', data: m.trend.map(t => t.revenue), borderColor: '#2F6FED', backgroundColor: 'rgba(47,111,237,0.08)', fill: false, tension: 0.3 }
    ]
  },
  options: { plugins: { legend: { position: 'bottom' } } }
};
const chartUrl = 'https://quickchart.io/chart?width=560&height=260&backgroundColor=white&version=4&c=' + encodeURIComponent(JSON.stringify(chartConfig));

function fmtInr(n) { return '₹' + Math.round(n).toLocaleString('en-IN'); }
function deltaBadge(pct) {
  const flat = pct === 0;
  const up = pct > 0;
  const color = flat ? '#5B6068' : (up ? '#1E9E6B' : '#D5493F');
  const arrow = flat ? '\u2192' : (up ? '\u25B2' : '\u25BC');
  return `<span style="color:${color};font-weight:600;font-size:12px;">${arrow} ${Math.abs(pct)}%</span>`;
}
function kpiCard(label, value, pct) {
  return `<td width="50%" style="padding:14px 10px;background:#F8F7F4;border:1px solid #E4E3DD;border-radius:8px;text-align:center;">` +
    `<div style="font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:#90959D;margin-bottom:6px;">${label}</div>` +
    `<div style="font-family:Georgia,serif;font-size:20px;font-weight:700;color:#16181C;">${value}</div>` +
    `<div style="margin-top:4px;font-size:11px;color:#5B6068;">${deltaBadge(pct)} vs yesterday</div></td>`;
}

const anomalyHtml = m.anomalies.length
  ? `<tr><td style="padding:14px 18px;background:#FBEFE9;border-left:3px solid #C68A1E;border-radius:6px;font-size:13px;color:#5B6068;">` +
    `<strong style="color:#16181C;">\u26A0 ${m.anomalies.length} channel(s) below the 2.2x ROAS floor:</strong> ${m.anomalies.map(a => a.channel + ' (' + a.roas + 'x)').join(', ')}</td></tr>`
  : `<tr><td style="padding:14px 18px;background:#EAF7F1;border-left:3px solid #1E9E6B;border-radius:6px;font-size:13px;color:#5B6068;">` +
    `<strong style="color:#16181C;">\u2713 All channels healthy</strong> — nothing below the 2.2x ROAS floor today.</td></tr>`;

const actionsHtml = m.actions.map(a => `<li style="margin-bottom:8px;">${a}</li>`).join('');
const summaryLabel = m.summary_source === 'gemini' ? 'Executive Summary (AI-written)' : 'Executive Summary (auto-generated)';

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head><body style="margin:0;padding:0;">` +
  `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;background:#FFFFFF;">` +
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#16181C;border-radius:10px 10px 0 0;">` +
  `<tr><td style="padding:20px 24px;">` +
  `<div style="font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:#6E9CFF;font-weight:700;">MarkOS AI &middot; Daily Morning Brief</div>` +
  `<div style="font-family:Georgia,serif;font-size:22px;color:#FFFFFF;font-weight:700;margin-top:4px;">${m.date}</div>` +
  `</td></tr></table>` +
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E3DD;border-top:none;border-radius:0 0 10px 10px;">` +
  `<tr><td style="padding:20px;">` +
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="8"><tr>${kpiCard('Revenue', fmtInr(m.revenue), m.deltas.revenue)}${kpiCard('Spend', fmtInr(m.spend), m.deltas.spend)}</tr>` +
  `<tr>${kpiCard('Blended ROAS', m.roas + 'x', m.deltas.roas)}${kpiCard('Leads', m.leads, m.deltas.leads)}</tr></table>` +
  `<div style="margin-top:20px;padding:12px 16px;background:#F1F0EC;border-radius:8px;font-size:13px;color:#5B6068;">` +
  `<strong style="color:#16181C;">Budget pacing:</strong> ${m.budget_pacing_pct}% of the expected month-to-date rate (₹${Math.round(m.mtd_spend).toLocaleString('en-IN')} spent of a ₹${(m.monthly_budget/100000).toFixed(1)}L monthly budget).</div>` +
  `<div style="margin-top:20px;"><img src="${chartUrl}" width="560" alt="8-day spend vs revenue trend" style="width:100%;max-width:560px;border-radius:8px;border:1px solid #E4E3DD;"></div>` +
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:20px;">${anomalyHtml}</table>` +
  `<div style="margin-top:22px;"><div style="font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#90959D;margin-bottom:8px;">${summaryLabel}</div>` +
  `<p style="font-size:14px;line-height:1.7;color:#16181C;margin:0;">${m.summary_text}</p></div>` +
  `<div style="margin-top:22px;"><div style="font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#90959D;margin-bottom:8px;">Recommended Actions</div>` +
  `<ol style="margin:0;padding-left:20px;font-size:13.5px;line-height:1.7;color:#16181C;">${actionsHtml}</ol></div>` +
  `<div style="margin-top:26px;padding-top:14px;border-top:1px solid #E4E3DD;font-size:11px;color:#90959D;">Generated automatically by the MarkOS AI n8n workflow. Sample/demo data — not a real business's figures.</div>` +
  `</td></tr></table></div></body></html>`;

return [{ json: { html, date: m.date } }];
